def main():
    ROOT.mkdir(exist_ok=True)
    (ROOT / "literature_register.json").write_text(json.dumps(records, indent=2, ensure_ascii=False)+"\n")
    (ROOT / "equation_map.json").write_text(json.dumps(equations, indent=2, ensure_ascii=False)+"\n")
    # Independent direct quadrature and straight-pipe limit for thesis Eq 2.5.
    mu, length, d1, d2 = .0034, .2, .02, .01
    steps=100000
    dx=length/steps
    integral=sum(128*mu/(math.pi*(d1+(d2-d1)*(i+.5)/steps)**4)*dx for i in range(steps))
    corrected=128*mu*length/(3*math.pi*(d1-d2))*(d2**-3-d1**-3)
    printed=3*corrected
    assert abs(integral/corrected-1)<1e-9
    checks={"taper_inputs":{"mu_Pa_s":mu,"length_m":length,"din_m":d1,"dout_m":d2},"numerical_integral_Pa_s_per_m3":integral,"corrected_closed_form_Pa_s_per_m3":corrected,"printed_expression_Pa_s_per_m3":printed,"relative_quadrature_error":abs(integral/corrected-1),"equal_diameter_limit":"Corrected: 128 mu L/(pi D^4). Printed: three times this.","scope":"Checks the printed equation only; original simulation code not inspected.","baseline_net_mL_per_pulse":5000/75,"baseline_period_s":60/75,"baseline_50mm_full_fill_travel_mm":(5000/75)*1e-6/(math.pi*.05**2/4)*1000}
    (ROOT/"algebra_verification.json").write_text(json.dumps(checks,indent=2)+"\n")
    print(json.dumps(checks,indent=2))

if __name__ == "__main__":
    main()
